package net.civeira.phylax.feature.observe.observedissuecomment.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissuecomment.domain.ObservedIssueComment;
import net.civeira.phylax.feature.observe.observedissuecomment.domain.valueobject.AuthorVO;

class AuthorValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of author of observed issue comment")
  void test_author_value_holder_assign_plain_value() {
    Object holder = new Object();
    AuthorValueHolder<Object> value = new AuthorValueHolder<>(holder);
    Assertions.assertSame(holder, value.author("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getAuthorValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getAuthor().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of author of observed issue comment")
  void test_author_value_holder_assign_value_object() {
    Object holder = new Object();
    AuthorValueHolder<Object> value = new AuthorValueHolder<>(holder);
    AuthorVO vo = AuthorVO.from("one");
    Assertions.assertFalse(value.getAuthorValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.author(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getAuthorValue().orElseThrow());
    Assertions.assertSame(holder, value.author(Optional.empty()));
    Assertions.assertFalse(value.getAuthorValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.author(Optional.of(vo)));
    Assertions.assertSame(vo, value.getAuthorValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of author of observed issue comment against the original")
  void test_author_value_holder_read() {
    Object holder = new Object();
    AuthorValueHolder<Object> value = new AuthorValueHolder<>(holder);
    AuthorVO vo = AuthorVO.from("one");
    AuthorVO other = AuthorVO.from("one");
    ObservedIssueComment original = Mockito.mock(ObservedIssueComment.class);
    Mockito.when(original.getAuthorValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readAuthor(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readAuthor(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.author(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readAuthor(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readAuthor(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of author of observed issue comment")
  void test_author_value_holder_unset() {
    Object holder = new Object();
    AuthorValueHolder<Object> value = new AuthorValueHolder<>(holder);
    AuthorVO vo = AuthorVO.from("one");
    value.author(vo);
    Assertions.assertSame(holder, value.unsetAuthorIfMatches("author_other"));
    Assertions.assertTrue(value.getAuthorValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetAuthorIfMatches("author"));
    Assertions.assertFalse(value.getAuthorValue().isPresent(),
        "The field name must clear the value");
    value.author(vo);
    Assertions.assertSame(holder, value.unsetAuthor());
    Assertions.assertFalse(value.getAuthorValue().isPresent(), "Unset must clear the value");
  }
}
